static inline const char *FFXIInternal_FindPCLabel(int raceIndex, int slot, int index)
{
    if (raceIndex < 0 || raceIndex >= (int)(sizeof(kFFXIInternalPCLists) / sizeof(kFFXIInternalPCLists[0])) ||
        slot < 0 || slot >= 11)
        return nullptr;

    const FFXIInternalList &list = kFFXIInternalPCLists[raceIndex][slot];
    for (int i = 0; i < list.count; ++i)
    {
        if (list.entries[i].index == index)
            return list.entries[i].label;
    }
    return nullptr;
}
